  default: "bg-(--caramel)",
  success: "bg-(--success)",
  warning: "bg-(--warning)",
  destructive: "bg-(--destructive)",
};

export const ProgressBar = ({ 
  value, 
  max = 100, 
  size = "md", 
  variant = "default", 
  showLabel = false,
