import React, { useState } from "react";
import { cn } from "@/lib/utils";
import { ChevronRight, X } from "lucide-react";

export interface SidebarSection {
  title: string;
  items: Array<{
    label: string;
    href?: string;
    icon?: React.ReactNode;
    active?: boolean;
    disabled?: boolean;
  }>;
}

export interface SidebarProps {
  sections: SidebarSection[];
  open?: boolean;
  onClose?: () => void;
  title?: string;
  className?: string;
  width?: "sm" | "md" | "lg";
  variant?: "fixed" | "inline";
}

const widthStyles = {
  sm: "w-64",
  md: "w-80",
  lg: "w-96",
};

export const Sidebar = ({ sections, open = true, onClose, title, className, width = "md", variant = "fixed" }: SidebarProps) => {
  const [collapsedSections, setCollapsedSections] = useState<Set<string>>(new Set());

  const toggleSection = (sectionTitle: string) => {
    const newCollapsed = new Set(collapsedSections);
    if (newCollapsed.has(sectionTitle)) {
      newCollapsed.delete(sectionTitle);
    } else {
      newCollapsed.add(sectionTitle);
    }
    setCollapsedSections(newCollapsed);
  };

  if (!open) return null;

  return (
    <aside
      className={cn(
        variant === "fixed"
          ? cn("fixed left-0 top-0 h-full shadow-lg z-40 border-r", widthStyles[width])
          : "relative h-full w-full",
        "bg-(--surface-card) border-(--border)",
        className
      )}
      role="navigation"
      aria-label="Sidebar navigation"
    >
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-(--border)">
